    }

    private static Instant parseInstant(JsonNode node) {
        String text = CheckoutService.text(node);
        if (text == null) {
            return null;
        }
        try {
            return OffsetDateTime.parse(text).toInstant();
        } catch (DateTimeParseException e) {
            return null;
        }
    }
}
