        }''','''        // atomic "insert if absent" so that two service instances can race safely
        String sql = postgres
                ? "INSERT INTO customers (cpf, email, credit_balance) VALUES (?, ?, 0) ON CONFLICT (cpf) DO NOTHING"
                : "INSERT INTO customers (cpf, email, credit_balance) SELECT CAST(? AS VARCHAR), CAST(? AS VARCHAR), 0 "
                + "WHERE NOT EXISTS (SELECT 1 FROM customers WHERE cpf = ?)";
        try (PreparedStatement ps = c.prepareStatement(sql)) {
            ps.setString(1, cpf);
            ps.setString(2, email);
            if (!postgres) {
                ps.setString(3, cpf);
            }
            ps.executeUpdate();
        }''')
open(p,'w').write(s)
